s:start}\\n@media(max-width:900px){.aa-ct-grid{grid-template-columns:1fr}}\\n.aa-ct-card{background:var(--aa-low);border:1px solid var(--aa-line);border-radius:16px;padding:32px}\\n.aa-ct-card h2{color:var(--aa-tx);font-size:22px;font-weight:700;margin:0 0 6px}\\n.aa-ct-card>p.aa-ct-sub{color:var(--aa-dim);font-size:14px;margin:0 0 26px}\\n.aa-field{display:block;margin-bottom:16px}\\n.aa-field>span{display:block;color:var(--aa-warm);font-size:12.5px;font-weight:700;letter-spacing:.03em;margin-bottom:7px}\\n.aa-field input,.aa-field select,.aa-field textarea{width:100%;background:var(--aa-low);border:1px solid var(--aa-line2);border-radius:10px;padding:12px 14px;color:var(--aa-tx);font-size:14px;outline:none;font-family:inherit;box-sizing:border-box}\\n.aa-field select{appearance:none;-webkit-appearance:none;padding-right:36px;background-image:url(\\\"data:image\\/svg+xml;charset=utf8,%3Csvg xmlns=\'http:\\/\\/www.w3.org\\/2000\\/svg\' width=\'16\' height=\'16\' fill=\'none\' stroke=\'%23ffc174\' stroke-width=\'2\' stroke-linecap=\'round\'%3E%3Cpath d=\'m4 6 4 4 4-4\'\\/%3E%3C\\/svg%3E\\\");background-repeat:no-repeat;background-position:right 12px center;cursor:pointer}\\n.aa-field select:focus,.aa-field input:focus,.aa-field textarea:focus{border-color:var(--aa-goldbg)}\\n.aa-field textarea{resize:vertical;min-height:120px}\\n.aa-cform-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}\\n@media(max-width:640px){.aa-cform-grid{grid-template-columns:1fr}}\\n.aa-cform-done,.aa-cform-err{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:600;border-radius:10px;padding:12px 14px;margin:0 0 16px}\\n.aa-cform-done{color:#5fd79a;background:rgba(52,199,123,.1);border:1px solid rgba(52,199,123,.35)}\\n.aa-cform-done[hidden],.aa-cform-err[hidden]{display:none}\\n.aa-cform-err{color:#ff9d8a;background:rgba(224,82,82,.1);border:1px solid rgba(224,82,82,.35)}\\n.aa-ct-side{display:grid;gap:16px}\\n.aa-ct-side-card{background:var(--aa-low);border:1px solid var(--aa-line);border-radius:14px;padding:24px}\\n.aa-ct-side-card .aa-ms{font-size:26px;color:var(--aa-goldbg);display:block;margin-bottom:10px}\\n.aa-ct-side-card h3{color:var(--aa-tx);font-size:16px;font-weight:700;margin:0 0 8px}\\n.aa-ct-side-card p{color:#b9bcc8;font-size:13.5px;line-height:1.75;margin:0 0 10px}\\n.aa-ct-side-card a{color:var(--aa-gold)!important;font-weight:700;text-decoration:none!important;font-size:13.5px}\\n.aa-faq{padding:56px 0 8px}\\n.aa-faq h2{font-size:clamp(24px,3vw,32px);font-weight:600;color:var(--aa-tx);margin:0 0 26px}\\n.aa-faq details{background:var(--aa-low);border:1px solid var(--aa-line);border-radius:12px;margin-bottom:12px;overflow:hidden}\\n.aa-faq summary{cursor:pointer;list-style:none;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:18px 20px;color:var(--aa-tx);font-weight:700;font-size:15px}\\n.aa-faq summary::-webkit-details-marker{display:none}\\n.aa-faq summary .aa-ms{color:var(--aa-goldbg);font-size:20px;flex:none;transition:transform .2s}\\n.aa-faq details[open] summary .aa-ms{transform:rotate(45deg)}\\n.aa-faq details p{color:#b9bcc8;font-size:14px;line-height:1.8;margin:0;padding:0 20px 20px}\\n<\\/style><section class=\\\"aa-ct\\\">\\n  <div class=\\\"aa-wrap\\\">\\n    <div class=\\\"aa-ct-grid\\\">\\n      <div class=\\\"aa-ct-card\\\">\\n        <h2>Send us a message<\\/h2>\\n        <p class=\\\"aa-ct-sub\\\">Order issues, download trouble, refund requests or author submissions &mdash; one form, one team, one working day.<\\/p>\\n        [aa_contact_form]\\n      <\\/div>\\n      <div class=\\\"aa-ct-side\\\">\\n        <div class=\\\"aa-ct-side-card\\\">\\n          <span class=\\\"aa-ms\\\">mail<\\/span>\\n          <h3>Support desk<\\/h3>\\n          <p>Email us any time &mdash; we reply within one working day, usually much faster.<\\/p>\\n          <a href=\\\"mailto:support@annaadhya.com\\\">support@annaadhya.com<\\/a>\\n        <\\/div>\\n        <div class=\\\"aa-ct-side-card\\\">\\n          <span class=\\\"aa-ms\\\">schedule<\\/span>\\n          <h3>Support hours<\\/h3>\\n          <p>Mon&ndash;Sat, 10:00&ndash;19:00 IST. Download links work around the clock even when we sleep.<\\/p>\\n        <\\/div>\\n        <div class=\\\"aa-ct-side-card\\\">\\n          <span class=\\\"aa-ms\\\">download<\\/span>\\n          <h3>Download &amp; refund help<\\/h3>\\n          <p>Link expired or payment twice? The fastest fixes live in our policies.<\\/p>\\n          <a href=\\\"\\/digital-delivery-policy\\/\\\">Digital delivery guide &rarr;<\\/a><br>\\n          <a href=\\\"\\/refund-policy\\/\\\">Refund policy &rarr;<\\/a>\\n        <\\/div>\\n      <\\/div>\\n    <\\/div>\\n  <\\/div>\\n<\\/section>\"},\"elements\":[]}]}]},{\"id\":\"aa310067\",\"elType\":\"section\",\"settings\":{\"gap\":\"no\",\"structure\":\"10\",\"stretch_section\":\"section-stretched\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"ab320067\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"ac330067\",\"elType\":\"widget\",\"widgetType\":\"html\",\"settings\":{\"html\":\"<section class=\\\"aa-faq\\\">\\n  <div class=\\\"aa-wrap\\\">\\n    <h2>Frequently asked questions<\\/h2>\\n    <details open>\\n      <summary>I paid but did not get my download. What now?<span class=\\\"aa-ms\\\">add<\\/span><\\/summary>\\n      <p>Seconds after payment the PDF is attached to a delivery email sent to the address you used at checkout &mdash; check spam first, then send us a message with your order number and we will re-send it the same day.<\\/p>\\n    <\\/details>\\n    <details>\\n      <summary>Can I read my ebook on Kindle or an iPad?<span class=\\\"aa-ms\\\">add<\\/span><\\/summary>\\n      <p>Yes. Every Annaadhya title is a standard PDF tested on phones, tablets, Kindle Scribe and desktops. Transfer it like any personal file &mdash; no special app needed.<\\/p>\\n    <\\/details>\\n    <details>\\n      <summary>My download link stopped working. Can I get another one?<span class=\\\"aa-ms\\\">add<\\/span><\\/summary>\\n      <p>Of course. The links in your delivery email never expire and there is no download limit &mdash; open the order page from your confirmation email and download again any time. See our <a href=\\\"\\/digital-delivery-policy\\/\\\" style=\\\"color:var(--aa-gold)\\\">Digital Delivery Policy<\\/a> for the details.<\\/p>\\n    <\\/details>\\n    <details>\\n      <summary>What is your refund policy?<span class=\\\"aa-ms\\\">add<\\/span><\\/summary>\\n      <p>If a download fails or a file is corrupted and we cannot fix it, you get a full refund. Tell us within 7 days of purchase with your order number. Full rules live in the <a href=\\\"\\/refund-policy\\/\\\" style=\\\"color:var(--aa-gold)\\\">Refund Policy<\\/a>.<\\/p>\\n    <\\/details>\\n    <details>\\n      <summary>Do you accept UPI, GPay and PhonePe?<span class=\\\"aa-ms\\\">add<\\/span><\\/summary>\\n      <p>Yes &mdash; UPI, RuPay, cards and netbanking all work at checkout through our payment gateway. Prices are in INR and include GST where applicable.<\\/p>\\n    <\\/details>\\n    <details>\\n      <summary>I am an author. How do I submit my manuscript?<span class=\\\"aa-ms\\\">add<\\/span><\\/summary>\\n      <p>We would love to read it. Use the form on this page with the topic &ldquo;Author submission&rdquo;, paste a 200-word synopsis and tell us where the full manuscript lives. Our editorial team replies to every serious submission.<\\/p>\\n    <\\/details>\\n  <\\/div>\\n<\\/section>\"},\"elements\":[]}]}]},{\"id\":\"aa310068\",\"elType\":\"section\",\"settings\":{\"gap\":\"no\",\"structure\":\"10\",\"stretch_section\":\"section-stretched\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"ab320068\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"ac330068\",\"elType\":\"widget\",\"widgetType\":\"html\",\"settings\":{\"html\":\"<style>\\n.aa-footer{background:var(--aa-bg);border-top:1px solid var(--aa-line);padding:64px 0 32px}\\n.aa-fgrid{display:grid;grid-template-columns:1.8fr 1fr 1fr 1fr 1fr;gap:34px;margin-bottom:48px}\\n@media(max-width:1024px){.aa-fgrid{grid-template-columns:1fr 1fr 1fr}}\\n@media(max-width:900px){.aa-fgrid{grid-template-columns:1fr 1fr}}\\n@media(max-width:560px){.aa-fgrid{grid-template-columns:1fr}}\\n.aa-fbrand-row{display:flex;align-items:center;gap:10px;margin-bottom:6px}\\n.aa-fbrand-row .aa-brand-ic{width:34px;height:34px}\\n.aa-fbrand-row .aa-brand-ic .aa-ms{font-size:19px}\\n.aa-fbrand-name{color:var(--aa-gold);font-weight:700;font-size:18px}\\n.aa-fbrand p{color:var(--aa-dim);font-size:14px;line-height:1.75;max-width:380px;margin:14px 0 20px}\\n.aa-paychips{display:flex;gap:8px;flex-wrap:wrap}\\n.aa-paychips span{font-size:10px;font-weight:700;letter-spacing:.06em;color:#a08e7a;background:var(--aa-cont);border:1px solid var(--aa-line2);border-radius:6px;padding:5px 9px}\\n.aa-fgrid h4{color:var(--aa-gold);font-size:16px;font-weight:600;margin:0 0 16px}\\n.aa-fgrid ul{list-style:none;margin:0;padding:0;display:grid;gap:10px}\\n.aa-fgrid ul a{color:var(--aa-dim)!important;text-decoration:none!important;font-size:14px;transition:color .15s}\\n.aa-fgrid ul a:hover{color:var(--aa-gold)!important}\\n.aa-fbottom{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:20px;border-top:1px solid var(--aa-line);padding-top:28px}\\n.aa-fsocial{display:flex;gap:10px}\\n.aa-fsocial a{width:36px;height:36px;border-radius:10px;background:var(--aa-cont);border:1px solid var(--aa-line2);display:flex;align-items:center;justify-content:center;color:var(--aa-dim)!important}\\n.aa-fsocial a:hover{color:var(--aa-gold)!important;border-color:var(--aa-gold)}\\n.aa-fsocial .aa-ms{font-size:18px}\\n.aa-fbottom p{color:var(--aa-dim);font-size:13px;margin:0}\\n.aa-fchips{display:flex;gap:10px;flex-wrap:wrap}\\n.aa-fchips span{font-size:10px;font-weight:700;letter-spacing:.08em;color:var(--aa-dim);background:var(--aa-cont);border:1px solid var(--aa-line2);border-radius:6px;padding:4px 8px}\\n<\\/style>\\n<footer class=\\\"aa-footer\\\">\\n  <div class=\\\"aa-wrap\\\">\\n    <div class=\\\"aa-fgrid\\\">\\n      <div class=\\\"aa-fbrand\\\">\\n        <div class=\\\"aa-fbrand-row\\\"><span class=\\\"aa-brand-ic\\\"><span class=\\\"aa-ms\\\">auto_stories<\\/span><\\/span><span class=\\\"aa-fbrand-name\\\">Annaadhya<\\/span><\\/div>\\n        <p>Empowering Indian readers with accessible, high-quality digital knowledge. Instantly downloadable PDFs optimized for phones, tablets and e-readers.<\\/p>\\n        <div class=\\\"aa-paychips\\\"><span>UPI<\\/span><span>RUPAY<\\/span><span>GPAY<\\/span><span>PHONEPE<\\/span><\\/div>\\n      <\\/div>\\n      <div>\\n        <h4>Shop<\\/h4>\\n        <ul>\\n          <li><a href=\\\"\\/shop\\/\\\">Bestsellers<\\/a><\\/li>\\n          <li><a href=\\\"\\/product-category\\/technology\\/\\\">Technology<\\/a><\\/li>\\n          <li><a href=\\\"\\/product-category\\/business\\/\\\">Business<\\/a><\\/li>\\n          <li><a href=\\\"\\/product-category\\/self-help\\/\\\">Self-Help<\\/a><\\/li>\\n          <li><a href=\\\"\\/product-category\\/fiction\\/\\\">Fiction<\\/a><\\/li>\\n          <li><a href=\\\"\\/shop\\/\\\">Bundles &amp; Deals<\\/a><\\/li>\\n        <\\/ul>\\n      <\\/div>\\n      <div>\\n        <h4>Company<\\/h4>\\n        <ul>\\n          <li><a href=\\\"\\/about\\/\\\">About Us<\\/a><\\/li>\\n          <li><a href=\\\"\\/contact\\/\\\">Contact Support<\\/a><\\/li>\\n          <li><a href=\\\"\\/contact\\/\\\">Author Submissions<\\/a><\\/li>\\n          <li><a href=\\\"\\/contact\\/\\\">Affiliate Program<\\/a><\\/li>\\n        <\\/ul>\\n      <\\/div>\\n      <div>\\n        <h4>Help<\\/h4>\\n        <ul>\\n          <li><a href=\\\"\\/contact\\/\\\">Contact Support<\\/a><\\/li>\\n          <li><a href=\\\"\\/about\\/\\\">About Us<\\/a><\\/li>\\n          <li><a href=\\\"\\/my-account\\/\\\">Wishlist<\\/a><\\/li>\\n          <li><a href=\\\"\\/cart\\/\\\">Shopping Cart<\\/a><\\/li>\\n          <li><a href=\\\"\\/web-admin\\/\\\">Site Admin<\\/a><\\/li>\\n        <\\/ul>\\n      <\\/div>\\n      <div>\\n        <h4>Legal<\\/h4>\\n        <ul>\\n          <li><a href=\\\"\\/privacy-policy\\/\\\">Privacy Policy<\\/a><\\/li>\\n          <li><a href=\\\"\\/terms\\/\\\">Terms &amp; Conditions<\\/a><\\/li>\\n          <li><a href=\\\"\\/refund-policy\\/\\\">Refund Policy<\\/a><\\/li>\\n          <li><a href=\\\"\\/digital-delivery-policy\\/\\\">Digital Delivery<\\/a><\\/li>\\n          <li><a href=\\\"\\/copyright-policy\\/\\\">Copyright Policy<\\/a><\\/li>\\n        <\\/ul>\\n      <\\/div>\\n    <\\/div>\\n    <div class=\\\"aa-fbottom\\\">\\n      <div class=\\\"aa-fsocial\\\">\\n        <a href=\\\"#\\\" aria-label=\\\"Instagram\\\"><span class=\\\"aa-ms\\\">photo_camera<\\/span><\\/a>\\n        <a href=\\\"#\\\" aria-label=\\\"LinkedIn\\\"><span class=\\\"aa-ms\\\">work<\\/span><\\/a>\\n        <a href=\\\"#\\\" aria-label=\\\"YouTube\\\"><span class=\\\"aa-ms\\\">smart_display<\\/span><\\/a>\\n        <a href=\\\"#\\\" aria-label=\\\"Telegram\\\"><span class=\\\"aa-ms\\\">send<\\/span><\\/a>\\n      <\\/div>\\n      <p>&copy; 2026 Annaadhya Ebooks. All rights reserved. Crafted for Indian readers.<\\/p>\\n      <div class=\\\"aa-fchips\\\"><span>100% SECURE CHECKOUT<\\/span><span>256-BIT ENCRYPTION<\\/span><\\/div>\\n    <\\/div>\\n  <\\/div>\\n  <script>\\n(function(){\\n  function refreshCart(){\\n    fetch(\\\"\\/?wc-ajax=aa_cart_count\\\",{headers:{\\\"Cache-Control\\\":\\\"no-cache\\\"}})\\n      .then(function(r){return r.ok?r.json():Promise.reject()})\\n      .then(function(d){var n=d&&d.count||0;\\n        document.querySelectorAll(\\\"[data-aa-cartcount]\\\").forEach(function(b){b.textContent=n;b.hidden=n<1})})\\n      .catch(function(){});\\n  }\\n  refreshCart();\\n  if(window.jQuery){jQuery(document.body).on(\\\"added_to_cart\\\",refreshCart)}\\n  document.addEventListener(\\\"click\\\",function(e){\\n    var t=e.target.closest?e.target.closest(\\\".add_to_cart_button\\\"):null;\\n    if(t){setTimeout(refreshCart,1500)}\\n  },true);\\n  var burger=document.querySelector(\\\".aa-burger\\\"),mm=document.querySelector(\\\".aa-mobile-menu\\\");\\n  if(burger&&mm){burger.addEventListener(\\\"click\\\",function(){mm.classList.toggle(\\\"open\\\")})}\\n  var ssheet=document.getElementById(\\\"aa-searchsheet\\\");\\n  if(ssheet){\\n    var ssIn=ssheet.querySelector(\\\"input\\\");\\n    document.querySelectorAll(\\\"[data-aa-search]\\\").forEach(function(tb){\\n      tb.addEventListener(\\\"click\\\",function(){ssheet.hidden=false;if(ssIn){ssIn.focus()}})\\n    });\\n    var ssx=ssheet.querySelector(\\\".aa-ss-x\\\");\\n    if(ssx){ssx.addEventListener(\\\"click\\\",function(){ssheet.hidden=true})}\\n    ssheet.addEventListener(\\\"click\\\",function(e){if(e.target===ssheet){ssheet.hidden=true}});\\n    document.addEventListener(\\\"keydown\\\",function(e){if(e.key===\\\"Escape\\\"){ssheet.hidden=true}});\\n  }\\n  var sp0=new URLSearchParams(location.search),st0=(sp0.get(\\\"book\\\")||sp0.get(\\\"s\\\")||\\\"\\\").trim();\\n  if(st0){\\n    var tt=document.querySelector(\\\"[data-aa-bookshelf-title]\\\"),ts=document.querySelector(\\\"[data-aa-bookshelf-sub]\\\");\\n    if(tt){tt.textContent=\\\"\\\";var em=document.createElement(\\\"span\\\");em.className=\\\"aa-grad\\\";em.textContent=\\\"\\\\u201C\\\"+st0+\\\"\\\\u201D\\\";tt.append(\\\"Results for \\\",em)}\\n    if(ts){ts.textContent=\\\"Every ebook matching your search \\\\u2014 instant PDF download, optimized for all devices.\\\"}\\n  }\\n  fetch(\\\"\\/wp-json\\/wc\\/store\\/v1\\/products\\/categories?per_page=30\\\")\\n    .then(function(r){return r.ok?r.json():Promise.reject()})\\n    .then(function(cats){\\n      var all=0;\\n      (cats||[]).forEach(function(c){\\n        all+=c.count||0;\\n        document.querySelectorAll(\\\"[data-aa-catcount]\\\").forEach(function(el){\\n          if(el.getAttribute(\\\"data-aa-catcount\\\")===c.slug){\\n            el.textContent=(c.count||0)+(c.count===1?\\\" Ebook\\\":\\\" Ebooks\\\")\\n          }\\n        });\\n        document.querySelectorAll(\\\"[data-aa-catnum]\\\").forEach(function(el){\\n          if(el.getAttribute(\\\"data-aa-catnum\\\")===c.slug){\\n            el.textContent=c.count||0\\n          }\\n        });\\n      });\\n      document.querySelectorAll(\\\"[data-aa-catnum]\\\").forEach(function(el){\\n        if(el.getAttribute(\\\"data-aa-catnum\\\")===\\\"_all\\\"){\\n          el.textContent=all\\n        }\\n      });\\n    })\\n    .catch(function(){});\\n  var sel=document.querySelector(\\\"[data-aa-sort]\\\"),grid=document.querySelector(\\\".aa-shopgrid .aa-products\\\");\\n  if(sel&&grid){sel.addEventListener(\\\"change\\\",function(){\\n    var items=[].slice.call(grid.querySelectorAll(\\\"li.aa-card\\\"));if(!items.length)return;\\n    var v=sel.value;\\n    items.sort(function(x,y){\\n      var px=parseFloat(x.getAttribute(\\\"data-price\\\"))||0,py=parseFloat(y.getAttribute(\\\"data-price\\\"))||0,\\n          tx=(x.getAttribute(\\\"data-title\\\")||\\\"\\\").toLowerCase(),ty=(y.getAttribute(\\\"data-title\\\")||\\\"\\\").toLowerCase();\\n      if(v===\\\"price_asc\\\")return px-py;\\n      if(v===\\\"price_desc\\\")return py-px;\\n      if(v===\\\"title\\\")return tx.localeCompare(ty);\\n      return 0});\\n    items.forEach(function(it){grid.appendChild(it)})})}\\n  var totalEl=document.querySelector(\\\"[data-aa-total]\\\");\\n  if(totalEl){\\n    var sp=new URLSearchParams(location.search);\\n    var q=sp.get(\\\"book\\\")||sp.get(\\\"s\\\")||\\\"\\\";\\n    fetch(\\\"\\/wp-json\\/wc\\/store\\/v1\\/products?per_page=1\\\"+(q?\\\"&search=\\\"+encodeURIComponent(q):\\\"\\\"))\\n      .then(function(r){var t=r.headers.get(\\\"X-WP-Total\\\");return t===null?Promise.reject():t})\\n      .then(function(total){\\n        var gridEl=document.querySelector(\\\".aa-shopgrid .aa-products\\\");\\n        var n=gridEl?gridEl.querySelectorAll(\\\"li.aa-card\\\").length:0;\\n        totalEl.innerHTML=\\\"Showing <strong>1&ndash;\\\"+n+\\\"<\\/strong> of <strong>\\\"+total+\\\"<\\/strong> ebooks\\\";\\n        totalEl.style.display=\\\"\\\";\\n      }).catch(function(){});\\n  }\\n  function toast(msg){var t=document.createElement(\\\"div\\\");t.className=\\\"aa-toast\\\";t.textContent=msg;document.body.appendChild(t);setTimeout(function(){t.classList.add(\\\"show\\\")},20);setTimeout(function(){t.classList.remove(\\\"show\\\");setTimeout(function(){t.remove()},300)},2600)}\\n  window.aaToast=toast;\\n  var nf=document.querySelector(\\\"[data-aa-news]\\\");\\n  if(nf){nf.addEventListener(\\\"submit\\\",function(e){e.preventDefault();\\n    var inp=nf.querySelector(\\\"input[type=email]\\\");var fd=new FormData();\\n    fd.append(\\\"action\\\",\\\"aa_newsletter_submit\\\");fd.append(\\\"email\\\",inp&&inp.value||\\\"\\\");\\n    var hp=nf.querySelector(\\\"[name=aa_hp]\\\");fd.append(\\\"hp\\\",hp?hp.value:\\\"\\\");\\n    fetch(\\\"\\/wp-admin\\/admin-ajax.php\\\",{method:\\\"POST\\\",body:fd})\\n      .then(function(r){return r.json()}).then(function(d){\\n        var done=document.querySelector(\\\"[data-aa-news-done]\\\"),err=document.querySelector(\\\"[data-aa-news-err]\\\");\\n        if(d&&d.status===\\\"ok\\\"){if(done)done.hidden=false;if(err)err.hidden=true;if(inp)inp.value=\\\"\\\";toast(\\\"Subscribed \\\\u2014 welcome aboard!\\\")}\\n        else{if(err){err.hidden=false;err.textContent=(d&&d.msg)||\\\"Something went wrong. Please try again.\\\"}}\\n      }).catch(function(){var done=document.querySelector(\\\"[data-aa-news-done]\\\");if(done)done.hidden=false});\\n  })}\\n  document.addEventListener(\\\"click\\\",function(e){\\n    var b=e.target.closest?e.target.closest(\\\".aa-wishbtn\\\"):null;if(!b)return;\\n    e.preventDefault();e.stopPropagation();\\n    var id=parseInt(b.getAttribute(\\\"data-id\\\")||\\\"0\\\",10);if(!id)return;\\n    var wl=[];try{wl=JSON.parse(localStorage.getItem(\\\"aa_wishlist\\\")||\\\"[]\\\")}catch(err){wl=[]}\\n    var i=wl.indexOf(id);var on=false;\\n    if(i>=0){wl.splice(i,1)}else{wl.push(id);on=true}\\n    try{localStorage.setItem(\\\"aa_wishlist\\\",JSON.stringify(wl))}catch(err){}\\n    b.classList.toggle(\\\"aa-on\\\",on);\\n    if(window.aaToast)toast(on?\\\"Saved to your wishlist\\\":\\\"Removed from wishlist\\\");\\n    document.dispatchEvent(new CustomEvent(\\\"aa-wishlist-change\\\"));\\n  },true);\\n  try{\\n    var wl0=JSON.parse(localStorage.getItem(\\\"aa_wishlist\\\")||\\\"[]\\\");\\n    document.querySelectorAll(\\\".aa-wishbtn\\\").forEach(function(b){\\n      if(wl0.indexOf(parseInt(b.getAttribute(\\\"data-id\\\")||\\\"0\\\",10))>=0)b.classList.add(\\\"aa-on\\\");\\n    });\\n  }catch(err){}\\n})();\\n  <\\/script>\\n<\\/footer>\"},\"elements\":[]}]}]}]'),
