rch<\\/span>\\n    <input type=\\\"search\\\" name=\\\"book\\\" placeholder=\\\"Search books, authors, topics...\\\" aria-label=\\\"Search books\\\">\\n    <button type=\\\"button\\\" class=\\\"aa-ss-x\\\" aria-label=\\\"Close search\\\"><span class=\\\"aa-ms\\\">close<\\/span><\\/button>\\n  <\\/form>\\n<\\/div>\"},\"elements\":[]}]}]},{\"id\":\"aa310065\",\"elType\":\"section\",\"settings\":{\"gap\":\"no\",\"structure\":\"10\",\"stretch_section\":\"section-stretched\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"ab320065\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"ac330065\",\"elType\":\"widget\",\"widgetType\":\"html\",\"settings\":{\"html\":\"<style>.aa-chead{position:relative;padding:46px 0 40px;border-bottom:1px solid var(--aa-line);background:var(--aa-bg);overflow:hidden}.aa-chead-glow{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:480px;height:220px;background:radial-gradient(closest-side,rgba(245,158,11,.1),transparent 70%);filter:blur(46px);pointer-events:none}.aa-chead .aa-crumb{display:flex;align-items:center;gap:8px;margin-bottom:18px}.aa-chead .aa-crumb a{font-size:11px;font-weight:700;letter-spacing:.08em;color:#a08e7a!important;text-decoration:none!important;text-transform:uppercase}.aa-chead .aa-crumb span.aa-cur{font-size:11px;font-weight:700;letter-spacing:.08em;color:var(--aa-goldbg);text-transform:uppercase}.aa-chead .aa-crumb .aa-ms{font-size:13px;color:#a08e7a}.aa-chead h1{font-size:clamp(30px,4vw,44px);font-weight:600;letter-spacing:-.02em;color:var(--aa-tx);margin:0}.aa-chead .aa-chead-sub{font-size:15px;color:var(--aa-warm);margin:12px 0 0}.aa-chead .aa-grad{background:linear-gradient(90deg,var(--aa-gold),var(--aa-tert));-webkit-background-clip:text;background-clip:text;color:transparent}.aa-chead .aa-wrap{position:relative}<\\/style><section class=\\\"aa-chead\\\"><