(24,1,'2026-11-15 10:56:54','2026-11-15 10:56:54','<!-- wp:cover {\"url\":\"http://localhost:8080/wp-content/uploads/2026/11/hero-banner.png\",\"id\":31,\"dimRatio\":45,\"minHeight\":480,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:480px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-45 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-31\" alt=\"\" src=\"http://localhost:8080/wp-content/uploads/2026/11/hero-banner.png\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"58px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#ffffff\"}}} -->\n<h1 class=\"wp-block-heading has-text-align-center\" style=\"color:#ffffff;font-size:58px;font-weight:700\">Books worth your screen time</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"20px\"},\"color\":{\"text\":\"#e9e7f2\"}}} -->\n<p class=\"has-text-align-center\" style=\"color:#e9e7f2;font-size:20px\">Practical, carefully made ebooks. Buy once, download instantly, read on any device.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"},\"style\":{\"spacing\":{\"margin\":{\"top\":\"1.4rem\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:1.4rem\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"10px\"},\"color\":{\"background\":\"#f9a825\",\"text\":\"#14213d\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/shop/\" style=\"border-radius:10px;color:#14213d;background-color:#f9a825\">Browse the Shop</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"style\":{\"border\":{\"radius\":\"10px\"},\"color\":{\"background\":\"#ffffff\",\"text\":\"#14213d\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/about/\" style=\"border-radius:10px;color:#14213d;background-color:#ffffff\">Why Annaadhya</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"3.5rem\",\"bottom\":\"1rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:3.5rem;padding-bottom:1rem\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"34px\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"font-size:34px\">Featured ebooks</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#5f6470\"}}} -->\n<p class=\"has-text-align-center\" style=\"color:#5f6470\">Fresh from the press - instant PDF download after checkout.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:shortcode -->[products limit=\"4\" columns=\"4\" orderby=\"date\" order=\"DESC\"]<!-- /wp:shortcode --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:3rem;padding-bottom:3rem\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"34px\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"font-size:34px\">Browse by category</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#5f6470\"}}} -->\n<p class=\"has-text-align-center\" style=\"color:#5f6470\">Find your next read in seconds.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:shortcode -->[product_categories number=\"4\" columns=\"4\" parent=\"0\" hide_empty=\"0\"]<!-- /wp:shortcode --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"gradient\":\"linear-gradient(135deg,#14213d 0%,#2a2d6e 55%,#5e2d96 100%)\"},\"spacing\":{\"padding\":{\"top\":\"3.5rem\",\"bottom\":\"3.5rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"background:linear-gradient(135deg,#14213d 0%,#2a2d6e 55%,#5e2d96 100%);padding-top:3.5rem;padding-bottom:3.5rem\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontSize\":\"30px\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"color:#ffffff;font-size:30px\">Instant delivery</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#c9cbe4\"}}} -->\n<p class=\"has-text-align-center\" style=\"color:#c9cbe4\">Your ebook lands in your inbox and account the second checkout completes. No shipping, no waiting.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontSize\":\"30px\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"color:#ffffff;font-size:30px\">Secure checkout</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#c9cbe4\"}}} -->\n<p class=\"has-text-align-center\" style=\"color:#c9cbe4\">Encrypted payments and protected download links. Your files stay safe and re-downloadable anytime.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontSize\":\"30px\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"color:#ffffff;font-size:30px\">Read anywhere</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#c9cbe4\"}}} -->\n<p class=\"has-text-align-center\" style=\"color:#c9cbe4\">Clean PDF layouts that work on phone, tablet, laptop and e-reader. Buy once, keep forever.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"4rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:3rem;padding-bottom:4rem\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"34px\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"font-size:34px\">Start reading tonight</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#5f6470\"}}} -->\n<p class=\"has-text-align-center\" style=\"color:#5f6470\">Pick a title, complete checkout, and your download link is ready before your tea gets cold.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"},\"style\":{\"spacing\":{\"margin\":{\"top\":\"1.2rem\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:1.2rem\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"10px\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/shop/\" style=\"border-radius:10px\">Shop all ebooks</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#8a8f9c\"},\"typography\":{\"fontSize\":\"14px\"}}} -->\n<p class=\"has-text-align-center\" style=\"color:#8a8f9c;font-size:14px\"><em>Store demo note: all six titles are sample content for testing the buying flow.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Home','','publish','closed','close